// Generated by Claude Sonnet 5. Not hand-written by the project author.
//
// Measures wall-clock time around a full native process invocation
// (spawn + interpret + exit), which is not perfectly apples-to-apples with
// the in-process `timeWasmRun` (process spawn overhead vs. constructing a
// LoxRunner object) but is comparable in that both include some form of
// per-run startup cost, and it's what an end user actually experiences on
// each side.

import { spawnSync } from 'node:child_process';
import { performance } from 'node:perf_hooks';

export interface NativeRunResult {
  ms: number;
  stdout: string;
  stderr: string;
  exitCode: number | null;
}

export function timeNativeRun(binaryPath: string, scriptPath: string): NativeRunResult {
  const start = performance.now();
  const result = spawnSync(binaryPath, [scriptPath], { encoding: 'utf8' });
  const ms = performance.now() - start;

  return {
    ms,
    stdout: result.stdout ?? '',
    stderr: result.stderr ?? '',
    exitCode: result.status,
  };
}
